#!/usr/bin/env bash
# check-dashboard-dist-modes.sh [repo-root]
#
# Fails if any committed file under internal/api/dashboardspa/dist/ has a git
# index mode other than 100644 (so no executable bit, no symlink).
#
# dist_in_sync_test compares content only; a bundle regenerated by a tool that
# writes 0755 or a symlink would pass it. The check reads the git index, never
# the working tree: remote Bazel runfiles normalize physical modes, so a
# filesystem stat cannot tell the committed mode.
set -euo pipefail

root="${1:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
dist="internal/api/dashboardspa/dist/"
want="100644"
bad=0

# NUL-delimited records ("<mode> <sha> <stage>\t<path>") survive any filename.
while IFS= read -r -d '' record; do
	mode="${record%% *}"
	path="${record#*$'\t'}"
	if [[ "$mode" != "$want" ]]; then
		printf 'check-dashboard-dist-modes: %q has mode %s, want %s\n' "$path" "$mode" "$want" >&2
		bad=1
	fi
done < <(git -C "$root" ls-files -s -z -- "$dist")

if [[ "$bad" -ne 0 ]]; then
	echo "check-dashboard-dist-modes: committed files under $dist must be mode $want (fix: git update-index --chmod=-x <path>)" >&2
	exit 1
fi
